export function parseSubscriptionFromRow(row: unknown): Subscription {
  if (!row || typeof row !== 'object') throw new Error('Invalid subscription data');
  const data = row as Record<string, unknown>;
  if (typeof data.user_id !== 'string') throw new Error('Invalid user_id');
  if (!isValidTier(data.tier)) throw new Error(`Invalid tier: ${data.tier}`);
  const features = JSON.parse(data.features as string);
  if (!Array.isArray(features)) throw new Error('Features must be array');
  return { userId: data.user_id, tier: data.tier, ... };
}

